import pdfplumber
import pandas as pd
import json

def clean_currency(x):
    if isinstance(x, str):
        return int(x.replace(',', ''))
    return x

def clean_float(x):
    if isinstance(x, str):
        return float(x)
    return x

def clean_int(x):
    if isinstance(x, str):
        return int(x)
    return x

import numpy as np

def to_native(x):
    if isinstance(x, (np.integer, np.int64)):
        return int(x)
    if isinstance(x, (np.floating, np.float64)):
        return float(x)
    return x

def main():
    # 1. Extract PDF Data
    pdf_rows = []
    headers = None

    with pdfplumber.open("/root/employees_backup.pdf") as pdf:
        for page in pdf.pages:
            tables = page.extract_tables()
            for table in tables:
                for row in table:
                    if not row: continue
                    # Assume first row of first page is header
                    if row[0] == 'ID':
                        if headers is None:
                            headers = row
                        continue
                    pdf_rows.append(row)

    df_pdf = pd.DataFrame(pdf_rows, columns=headers)

    # Clean PDF Data types
    # Salary: "112,000" -> 112000
    df_pdf['Salary'] = df_pdf['Salary'].apply(clean_currency)
    # Years: "7" -> 7
    df_pdf['Years'] = df_pdf['Years'].apply(clean_int)
    # Score: "4.3" -> 4.3
    df_pdf['Score'] = df_pdf['Score'].apply(clean_float)

    # 2. Extract Excel Data
    df_xlsx = pd.read_excel("/root/employees_current.xlsx")

    # Ensure types match (Excel might read mixed types if there are NaNs, though we saw int/float)
    # But explicitly casting helps safety
    # Assuming 'ID' is string in both

    # Index by ID for easier comparison
    df_pdf.set_index('ID', inplace=True)
    df_xlsx.set_index('ID', inplace=True)

    # 3. Identify Differences

    # Deleted Employees (In PDF but not in Excel)
    pdf_ids = set(df_pdf.index)
    xlsx_ids = set(df_xlsx.index)

    deleted_ids = sorted(list(pdf_ids - xlsx_ids))

    # Modified Employees
    common_ids = pdf_ids.intersection(xlsx_ids)
    modified_employees = []

    # Columns to compare (all columns present in both)
    # We observed columns are same: ['First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']
    columns_to_compare = [c for c in df_pdf.columns if c in df_xlsx.columns]

    for emp_id in common_ids:
        pdf_row = df_pdf.loc[emp_id]
        xlsx_row = df_xlsx.loc[emp_id]

        for col in columns_to_compare:
            pdf_val = pdf_row[col]
            xlsx_val = xlsx_row[col]

            # Handle potential type mismatches or floating point epsilon
            is_diff = False
            if isinstance(pdf_val, float) and isinstance(xlsx_val, float):
                if abs(pdf_val - xlsx_val) > 1e-9:
                    is_diff = True
            else:
                if pdf_val != xlsx_val:
                    is_diff = True

            if is_diff:
                modified_employees.append({
                    "id": emp_id,
                    "field": col,
                    "old_value": to_native(pdf_val),
                    "new_value": to_native(xlsx_val)
                })

    # Sort modified employees by ID
    modified_employees.sort(key=lambda x: x['id'])

    # 4. Generate Report
    report = {
        "deleted_employees": deleted_ids,
        "modified_employees": modified_employees
    }

    with open("/root/diff_report.json", "w") as f:
        json.dump(report, f, indent=2)

    print("Report generated at /root/diff_report.json")

if __name__ == "__main__":
    main()
